// Freshness filter: keep only posts published in the last 24 hours.
// If nothing is new, this returns zero items and the workflow quietly stops —
// no drafts, no email, no noise. Production builds add a proper
// de-duplication store so a post can never be drafted twice.
const DAY_MS = 24 * 60 * 60 * 1000;
const now = Date.now();
return $input.all().filter(item => {
  const published = new Date(item.json.pubDate || 0).getTime();
  return published > 0 && (now - published) < DAY_MS;
});

