// The AI returns one JSON object; turn it into one row per platform
// so each draft can be reviewed, edited and approved on its own line.
const raw = $input.first().json.choices[0].message.content;
let drafts;
try {
  drafts = JSON.parse(raw);
} catch (e) {
  throw new Error('The AI reply was not valid JSON. First 200 characters: ' + raw.slice(0, 200));
}
const post = $('Normalise Post').first().json;
const rows = [];
for (const platform of ['linkedin', 'x', 'facebook']) {
  if (drafts[platform]) {
    rows.push({ json: {
      platform: platform,
      draft_text: drafts[platform],
      source_title: post.title,
      source_url: post.link,
      status: 'Pending review'
    }});
  }
}
return rows;

